fn solve(x: i32) -> i32 {
    let x_str = x.to_string();
    let digit_char = x_str.chars().next().unwrap();
    let digit = digit_char.to_digit(10).unwrap() as i32;
    let length = x_str.len() as i32;
    
    // Calculate the score
    // For each previous digit (1..digit-1), we typed 1+2+3+4 = 10 presses
    let presses_before_digit = (digit - 1) * 10;
    
    // For the current digit, we typed lengths 1..length
    let presses_for_current_digit = (1..=length).sum::<i32>();
    
    presses_before_digit + presses_for_current_digit
}